with target as(select isbn13,content_hash,candidate||jsonb_build_object('cover_url','https://www.hakusensha.co.jp/wp_hakusensha/postimage/2016/lists/9784592186175.jpg','cover_hash','2afe998d94ac8842a86eb0f1084dab01ee8499d7b981b53d77900b1ff3e53402','source_url','https://www.hakusensha.co.jp/comicslist/44543/','cover_reference_before_correction',jsonb_build_object('cover_url',candidate->>'cover_url','cover_hash',candidate->>'cover_hash','source_url',candidate->>'source_url')) as new_candidate from public.book_content_review_jobs where isbn13='9784592186175' and content_hash='bab0785ad41241e5545bd803cf042ab2099bca33322c8fc8382d604e378f9a05' and adult_only is null and status='pending_review' and cover_status='unreviewed'),fixed as(update public.book_content_review_jobs j set candidate=t.new_candidate,content_hash=encode(sha256(convert_to(t.new_candidate::text,'UTF8')),'hex'),reason='文字のみの代替画像を、ISBN一致の白泉社公式表紙へ修正。分類・公開許可は維持。',updated_at=now() from target t where j.isbn13=t.isbn13 and j.content_hash=t.content_hash returning j.isbn13),confirmed as(insert into public.book_metadata_overrides(isbn,normalized_isbn,title,series_title,series_key,volume_number,author,publisher,thumbnail_url,source_url,source,enabled) select isbn13,isbn13,'スキップ・ビート！ 27','スキップ・ビート！','スキップビート',27,'仲村佳樹','白泉社','https://www.hakusensha.co.jp/wp_hakusensha/postimage/2016/lists/9784592186175.jpg','https://www.hakusensha.co.jp/comicslist/44543/','developer',true from fixed on conflict(normalized_isbn) where normalized_isbn is not null do nothing returning normalized_isbn) select (select count(*) from fixed) as corrected,(select count(*) from confirmed) as confirmed;
